end

function Page:Build(parent)
 local C=HolyStorm.UI.Components;local p=CreateFrame("Frame",nil,parent);self.page=p;local root=C:CreateColumn(p,{frame=p,gap=8,padding={left=12,right=12,top=8,bottom=10}});root:Add(C:CreateText(p,{text=L["INSPECTOR_TITLE"],font="GameFontHighlightLarge"}),{height=26})
 local inputs=C:CreateRow(p,{gap=8});local function labeled(label,control,track)local column=C:CreateColumn(inputs.frame,{gap=2});column:Add(C:CreateText(column.frame,{text=label,font="GameFontNormalSmall"}),{height=16});column:Add(control,{height=22});inputs:Add(column,track);return control end
 self.character=labeled(L["CHARACTER"],HolyStorm.PolicyUI:CreateSelector(inputs.frame,240,function()return HolyStorm.PolicyUI:CharacterItems()end),{weight=2,minWidth=180});self.permission=labeled(L["ACTION"],HolyStorm.PolicyUI:Edit(inputs.frame,220),{weight=2,minWidth=150});self.permission:SetText(defaultPermission());self.target=labeled(L["TARGET"],HolyStorm.PolicyUI:Edit(inputs.frame,160),{weight=1.5,minWidth=110});self.filter=labeled(L["FILTER"],HolyStorm.PolicyUI:Edit(inputs.frame,160),{weight=1.5,minWidth=110});self.filterScope=labeled(L["SCOPE"],HolyStorm.PolicyUI:Edit(inputs.frame,90),{width=100});self.filterScope:SetText(DEFAULT_SCOPE);root:Add(inputs,{height=42})
 local actions=C:CreateRow(p,{gap=6});local inspect=HolyStorm.PolicyUI:Button(actions.frame,L["ANALYSIS"],100,function()Page:Inspect()end);actions:Add(inspect,{width=100});root:Add(actions,{height=24});local scroll,text=HolyStorm.PolicyUI:CreateTextPanel(p);self.output=text;root:Add(scroll,{weight=1,minHeight=260});root:Relayout();return p
end
